"use strict";

const INITIAL_PAYLOAD = {"version":2,"iterations":600000,"salt":"e/JW2cj3azBRw8ebwDauaw==","iv":"8Afw1xCKcN759gmf","ciphertext":""};
const STORAGE_KEY = "jimmy-chen-cpd-records-v1";

const lockPanel = document.querySelector("#cpd-lock-panel");
const loginForm = document.querySelector("#cpd-login-form");
const passcodeInput = document.querySelector("#cpd-passcode");
const loginMessage = document.querySelector("#cpd-login-message");
const workspace = document.querySelector("#cpd-workspace");
const summary = document.querySelector("#cpd-summary");
const searchInput = document.querySelector("#cpd-search");
const tableBody = document.querySelector("#cpd-table-body");
const emptyMessage = document.querySelector("#cpd-empty-message");
const statusMessage = document.querySelector("#cpd-status-message");
const editorDialog = document.querySelector("#cpd-editor-dialog");
const editorForm = document.querySelector("#cpd-editor-form");
const editorTitle = document.querySelector("#cpd-editor-title");
const editIndexInput = document.querySelector("#cpd-edit-index");
const editDateInput = document.querySelector("#cpd-edit-date");
const editActivityInput = document.querySelector("#cpd-edit-activity");
const editHoursInput = document.querySelector("#cpd-edit-hours");

let activePasscode = "";
let cpdData = null;

function bytesToBase64(bytes) {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

function base64ToBytes(value) {
  const binary = atob(value);
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}

async function deriveKey(passcode, salt, iterations) {
  const material = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(passcode),
    "PBKDF2",
    false,
    ["deriveKey"]
  );

  return crypto.subtle.deriveKey(
    { name: "PBKDF2", hash: "SHA-256", salt, iterations },
    material,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

async function decryptPayload(payload, passcode) {
  const salt = base64ToBytes(payload.salt);
  const iv = base64ToBytes(payload.iv);
  const ciphertext = base64ToBytes(payload.ciphertext);
  const key = await deriveKey(passcode, salt, payload.iterations);
  const plaintext = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ciphertext);
  return JSON.parse(new TextDecoder().decode(plaintext));
}

async function encryptPayload(data, passcode) {
  const iterations = INITIAL_PAYLOAD.iterations;
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await deriveKey(passcode, salt, iterations);
  const plaintext = new TextEncoder().encode(JSON.stringify(data));
  const ciphertext = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, plaintext);

  return {
    version: 1,
    iterations,
    salt: bytesToBase64(salt),
    iv: bytesToBase64(iv),
    ciphertext: bytesToBase64(new Uint8Array(ciphertext))
  };
}

function setMessage(element, message, isError = false) {
  element.textContent = message;
  element.classList.toggle("is-error", isError);
}

function normalizeCpdDate(value) {
  return value.replace(
    /\b(20\d{2})\.(0?[1-9]|1[0-2])\.(0?[1-9]|[12]\d|3[01])\b/g,
    (_, year, month, day) => `${year}.${Number(month)}.${Number(day)}`
  );
}

function normalizeCpdDates(data) {
  data.records = data.records.map((record) => ({
    ...record,
    date: normalizeCpdDate(record.date)
  }));
  return data;
}

function renderYearSummary(records) {
  const hoursByYear = new Map();
  for (const record of records) {
    const year = record.date.match(/^(20\d{2})/)?.[1];
    if (!year) continue;
    hoursByYear.set(year, (hoursByYear.get(year) || 0) + (Number.parseFloat(record.hours) || 0));
  }

  summary.replaceChildren();
  for (let year = 2022; year <= 2026; year += 1) {
    const item = document.createElement("span");
    item.className = "cpd-year-stat";

    const yearLabel = document.createElement("strong");
    yearLabel.textContent = String(year);

    const hoursLabel = document.createElement("span");
    const hours = hoursByYear.get(String(year)) || 0;
    hoursLabel.textContent = `${hours.toLocaleString("en-GB")} CPD hours`;

    item.append(yearLabel, hoursLabel);
    summary.append(item);
  }
}

function mergePublishedUpdate(savedData, publishedData) {
  const savedByDate = new Map(savedData.records.map((record) => [record.date, record]));
  const publishedDates = new Set(publishedData.records.map((record) => record.date));
  const locallyAdded = savedData.records.filter((record) => !publishedDates.has(record.date));
  const updatedPublished = publishedData.records.map((record) => savedByDate.get(record.date) || record);

  return {
    ...publishedData,
    records: [...locallyAdded, ...updatedPublished]
  };
}

function renderRecords() {
  const query = searchInput.value.trim().toLowerCase();
  const visibleRecords = cpdData.records
    .map((record, index) => ({ record, index }))
    .filter(({ record }) =>
      [record.date, record.activity, record.hours].join(" ").toLowerCase().includes(query)
    );

  tableBody.replaceChildren();

  for (const { record, index } of visibleRecords) {
    const row = document.createElement("tr");

    const dateCell = document.createElement("td");
    dateCell.textContent = record.date;

    const activityCell = document.createElement("td");
    activityCell.className = "cpd-activity-cell";
    activityCell.textContent = record.activity;

    const hoursCell = document.createElement("td");
    hoursCell.className = "cpd-hours-cell";
    hoursCell.textContent = record.hours;

    const actionsCell = document.createElement("td");
    actionsCell.className = "cpd-row-actions";

    const editButton = document.createElement("button");
    editButton.type = "button";
    editButton.className = "cpd-text-button";
    editButton.textContent = "Edit";
    editButton.addEventListener("click", () => openEditor(index));

    const deleteButton = document.createElement("button");
    deleteButton.type = "button";
    deleteButton.className = "cpd-text-button cpd-delete-button";
    deleteButton.textContent = "Delete";
    deleteButton.addEventListener("click", () => deleteRecord(index));

    actionsCell.append(editButton, deleteButton);
    row.append(dateCell, activityCell, hoursCell, actionsCell);
    tableBody.append(row);
  }

  renderYearSummary(cpdData.records);
  emptyMessage.hidden = visibleRecords.length !== 0;
}

async function saveRecords(message) {
  const encrypted = await encryptPayload(cpdData, activePasscode);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(encrypted));
  setMessage(statusMessage, message);
}

function openEditor(index = -1) {
  editIndexInput.value = String(index);
  if (index >= 0) {
    const record = cpdData.records[index];
    editorTitle.textContent = "Edit CPD record";
    editDateInput.value = record.date;
    editActivityInput.value = record.activity;
    editHoursInput.value = record.hours;
  } else {
    editorTitle.textContent = "Add CPD record";
    editorForm.reset();
    editIndexInput.value = "-1";
  }
  editorDialog.showModal();
  editDateInput.focus();
}

async function deleteRecord(index) {
  const record = cpdData.records[index];
  if (!window.confirm(`Delete the CPD record dated ${record.date}?`)) return;
  cpdData.records.splice(index, 1);
  await saveRecords("Record deleted and encrypted changes saved in this browser.");
  renderRecords();
}

async function unlockRecords(passcode) {
  const savedPayloadText = localStorage.getItem(STORAGE_KEY);
  let savedPayload = null;
  let publishedData;
  let migrationMessage = "";

  try {
    savedPayload = savedPayloadText ? JSON.parse(savedPayloadText) : null;
  } catch {
    savedPayload = null;
  }

  try {
    publishedData = await decryptPayload(INITIAL_PAYLOAD, passcode);
    cpdData = savedPayload ? await decryptPayload(savedPayload, passcode) : publishedData;

    if ((cpdData.dataVersion || 1) < (publishedData.dataVersion || 1)) {
      cpdData = mergePublishedUpdate(cpdData, publishedData);
      migrationMessage = "Published records were extended to page 18 and merged with this browser’s saved copy.";
    }
  } catch (error) {
    if (!savedPayload) throw error;
    cpdData = publishedData || await decryptPayload(INITIAL_PAYLOAD, passcode);
    migrationMessage = "The browser copy could not be opened, so the published records were loaded.";
  }

  cpdData = normalizeCpdDates(cpdData);

  activePasscode = passcode;
  if (migrationMessage) {
    const encrypted = await encryptPayload(cpdData, activePasscode);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(encrypted));
    setMessage(statusMessage, migrationMessage);
  }
  lockPanel.hidden = true;
  workspace.hidden = false;
  passcodeInput.value = "";
  renderRecords();
  searchInput.focus();
}

function lockRecords() {
  activePasscode = "";
  cpdData = null;
  tableBody.replaceChildren();
  workspace.hidden = true;
  lockPanel.hidden = false;
  setMessage(loginMessage, "");
  passcodeInput.focus();
}

function exportBackup() {
  const blob = new Blob([JSON.stringify(cpdData, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  const date = new Date().toISOString().slice(0, 10);
  link.href = url;
  link.download = `cpd-records-backup-${date}.json`;
  document.body.append(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
  setMessage(statusMessage, "Plaintext JSON backup exported. Store it securely.");
}

async function importBackup(file) {
  const imported = JSON.parse(await file.text());
  if (!imported || !Array.isArray(imported.records)) {
    throw new Error("The selected file is not a valid CPD backup.");
  }

  const validRecords = imported.records.every((record) =>
    record && typeof record.date === "string" && typeof record.activity === "string" &&
    (typeof record.hours === "string" || typeof record.hours === "number")
  );
  if (!validRecords) throw new Error("One or more CPD records are invalid.");

  cpdData = {
    title: typeof imported.title === "string" ? imported.title : "CPD Full Records",
    sourcePages: typeof imported.sourcePages === "string" ? imported.sourcePages : "User backup",
    records: imported.records.map((record) => ({
      date: normalizeCpdDate(record.date),
      activity: record.activity,
      hours: String(record.hours)
    }))
  };

  await saveRecords("Backup imported and encrypted in this browser.");
  renderRecords();
}

loginForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const passcode = passcodeInput.value.trim();
  if (!/^\d{6}$/.test(passcode)) {
    setMessage(loginMessage, "Enter a six-digit numeric passcode.", true);
    return;
  }

  setMessage(loginMessage, "Decrypting records…");
  try {
    await unlockRecords(passcode);
    setMessage(loginMessage, "");
  } catch {
    setMessage(loginMessage, "The passcode is incorrect or the encrypted data is unavailable.", true);
    passcodeInput.select();
  }
});

searchInput.addEventListener("input", renderRecords);
document.querySelector("#cpd-add-button").addEventListener("click", () => openEditor());
document.querySelector("#cpd-lock-button").addEventListener("click", lockRecords);
document.querySelector("#cpd-export-button").addEventListener("click", exportBackup);
document.querySelector("#cpd-dialog-close").addEventListener("click", () => editorDialog.close());
document.querySelector("#cpd-editor-cancel").addEventListener("click", () => editorDialog.close());

editorForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const index = Number.parseInt(editIndexInput.value, 10);
  const record = {
    date: normalizeCpdDate(editDateInput.value.trim()),
    activity: editActivityInput.value.trim(),
    hours: editHoursInput.value.trim()
  };

  if (!record.date || !record.activity || !record.hours) return;

  if (index >= 0) cpdData.records[index] = record;
  else cpdData.records.unshift(record);

  await saveRecords(index >= 0
    ? "Record updated and encrypted changes saved in this browser."
    : "Record added and encrypted changes saved in this browser.");
  editorDialog.close();
  renderRecords();
});

document.querySelector("#cpd-import-input").addEventListener("change", async (event) => {
  const [file] = event.target.files;
  if (!file) return;
  try {
    await importBackup(file);
  } catch (error) {
    setMessage(statusMessage, error.message || "The backup could not be imported.", true);
  } finally {
    event.target.value = "";
  }
});
